INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1432227-ce202', 'stk-user9306', 'CE 202', 'info', '{"desc": "السمستر 142\nاخذت هذي المادة مع الدكتور سعيد الغامدي طبعا هذا كورس مصغر بحيث انه تم دمج (ce-201 مع ce203) وهي خاصة لطلاب البتروليوم فقط على مااعتقد.\n\nطبعا يوجد كتاب لهذي المادة وهو مرجع الطالب بالاضافة الى الكويزات حقة الدكتور جدا مهمة .\n\nالمياجر:-سهلة وغالبا نفس المياجر القديمة مع تغير بسيط في الارقام\nالفاينل :-نفس وضع الميجر.\n\nالهوموروكات:- طبعا كنا ننسخ من المانيول سلوشن لكن القريدر كان شديد وخفس بنا خفس.\n\nواذا الدكتو ماتغير انصحكم تأخذون نوت معاه لان يجيب نفس الامثلة اللي هو يحلها خصوصا اذا كررالمثال اكثر من مرة (انتبه).", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-202-statics-strength-of-materials/120667/7", "user": "user9306", "ts": 1446743895000, "tid": 120667, "pn": 7}}', 1446743895000, 1794826836, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1447595-ce202', 'stk-user10620', 'CE 202', 'info', '{"desc": "أخذت كورس (CE 202 ) ترم 142 مع الدكتور. سعيد الغامدي , والكورس هذا يجمع أهم المواضيع من (CE 201,203 )\nوصراحة الكتاب المستخدم ممتاز نسيبا لكنه ما يساعد مع أسئلة الدكتور لشخص يبي يجيب في المادة (ِA,A+)\n\nوالكورس بشكل عام شوي ضغط فمثلا عندك :\n1- هومورك أسبوعي ( يختار لك أسئلة من الكتاب )\n2-المياجر طوال وطريقة الدكتور في الأسئلة تختلف 180 درجة عن طريقة الكتاب في الأسئلة\n3-الفاينل comprehensive فراح يتعبك من كثرة الشباتر\n\nلكن لكل مشكلة حل :\n1- الهومورك فيه مانوال سلوشن لنفس نسخة الكتاب\n2- أفضل طريقة أنك تذاكر للمياجر هي بس أنك تحل الاولد اقزام لأن طريقة الدكتور انه يجيبه نفسه مع تغيير بسيط في الارقام زي ما ذكروا الأخوان وكثير من الأحيان يجيب الأرقام نفسها وراح تجيب في الاول والثاني درجة ما تقل عن 90 من 100 في كل واحد فيهم وأسئل مجرب .\n3- الفاينل نفس طريقة المياجر بالضبط .\n\nوهذا الرابط وفي كل الاشياء الي تحتاجونها(من أولد اقزام و مانيوال سلوشين) هنا\n\nوصراحة كان واحد من أروع الكورسات الي مرت علي في الجامعة .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-202-statics-strength-of-materials/120667/8", "user": "user10620", "ts": 1461772436000, "tid": 120667, "pn": 8}}', 1461772436000, 1794826836, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1529546-ce202', 'stk-azizlake', 'CE 202', 'info', '{"desc": "TERM202 (ONLINE)\n\nالمواضيع التي يغطيها المقرر\nالمادة خليط بين CE201 (Statics) و CE203 (Solids)، إلى الميدتيرم راح تدرس ستاتيكس وبعدين تقلب للسوليدز والفاينل يركز عالسوليدز.\nالمادة ضااايعة مو زي 201 و 203، الدكاترة مايدرون وش يشرحون بالضبط وكل دكتور يركز على حاجة والكوردينيتر هو يكتب الميد والفاينل لكل الطلاب فيعني طلابه مستانسين.\nالكويزات والميد أسئلته مختلفة عن أسئلة الكتاب تماماً، أوّل يوم كانت المادة دكتور واحد يدرسها كانت أسهل بس يوم خلوها للميكانيكل وصارت كوردينيتيد “ضاعت الطاسة”.\nأفضل طريقة وجدتها للمذاكرة تبحث باليوتيوب عن أسم الدرس وتفهمه وتحل أسئلة Fundamental بالكتاب.\n\nالكتاب المستخدم للمقرر\nStatics and mechanics of material", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-202-statics-strength-of-materials/120667/9", "user": "AzizLake", "ts": 1618836295000, "tid": 120667, "pn": 9}}', 1618836295000, 1794826836, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p695804-ce202', 'stk-banyan', 'CE 202', 'info', '{"desc": "أعتقــد ان الكــورس بيكــون سهــل لعـــدة أسبـــاب:\n\nأولآ: لانـــه عبارة عــن كورسيـــن مدموجيــن ســـوا ومــن الصعــب ان التعمـــق فيهـــــم عشــان الوقتز\n\nثانيا: الكــورسين اثنيـــنهم مو صعبيـــن في الاصل\n\nثالثا: الدكتــــور اللي بيدرسهـــا … الدليجـــان … متساعد جدا مع الطلاب وأهم شـــي الطلاب يفهـــمون عندهـ\n\nرابعــا: الكورس مو كومن … يعني الدكتور بيمشي على كيفــــهـ وبهــدوء", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce202/94190/5", "user": "Banyan", "ts": 1283378941000, "tid": 94190, "pn": 5}}', 1283378941000, 1794826836, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-moh_ammed-ce202', 'stk-moh_ammed', 'CE 202', 'doc', '{"docs": [{"id": "stk-dr-f98555", "n": "Dr. Salah U. Al-Dulaijan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 202 - Term 211\nالتحضير: ينادي على الأسماء من بداية المحاضرة، وحتى لو جيت متأخر تقدر تروح له في نهاية المحاضرة ويحضرك.\n\nالتعامل: الدكتور حبيب ماشاء الله عليه.\n\nالشرح: أحيانا أسرح وما أركز معه دايم، بس بشكل عام فهو كويس.\n\nالصوت: كلامه مخلوط عربي وانجليزي، بس حاول تقعد قدام عشان تسمعه زين بالذات لو كانت القاعة كبيرة زي اللي كنا فيها.\n\nالكويزات: سهلة ،عطانا 8 واجبات تقريبا ومع تسليم كل واجب يكون فيه كويز ويكون سؤال واحد مأخوذ من نفس الواجب اللي سلمناه (كان يغير الأرقام بس)…آخر واجبين -أو آخر ثلاثة والله ما أتذكر- ماكان فيه عليهم كويز.\n\nإضافات: الدكتور دايم يحث الطلاب على السؤال، ومايتضايق من كثرة الأسئلة حتى لو كانت بسيطة. وماقصر معنا، كنا دايم نطلبه يغير موعد الكويز ويغيره.\nإذا جيت تحل الواجب حاول تكتب كل خطوات الحل؛ لأن التصحيح فيها كان شديد وممكن على خطوة تافهه انت ماكتبتها ممكن راح تنقص.\n\nبشكل عام الدكتور كويس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533323-ce202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-salah-u-al-dulaijan/98555/16", "user": "Moh_ammed", "ts": 1641391534000, "tid": 98555, "pn": 16}}]}', 1641391534000, 1794826836, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-someone33-ce202', 'stk-someone33', 'CE 202', 'doc', '{"docs": [{"id": "stk-dr-f98561", "n": "Dr. Naser Abdul-Rahman Al-Shayea", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "NASER A. AL-SHAYEA\nCE 202 - Term212\n\nبنود التقييم :\n\nالتحضير : التحضير نهاية الكلاس واحيان ما يحضر\n\nطريقة الشرح : شرح نايم وبالموت تفهم عليه، ونادر يحل سؤال بس يجلس يأشر بالماوس على خطوات الحل وما تفهم شي منه\n\nالكويزات : كويزاته سهله جداً واغلبها اسئلة كونسبت بسيطة\n\nالصوت: الصوت وااطي وفوق كذا يلبس كمامتين يعني تجلس قدام ويدوبك تسمعه\n\nإضافات : احيان يعطي نصايح ومعلومات حلوه لك كمهندس لكن شرحه سيء وما انصح احد ينزل عنده\n\nالتقييم النهائي : C", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535032-ce202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-naser-abdul-rahman-al-shayea/98561/8", "user": "SomeOne33", "ts": 1660606918000, "tid": 98561, "pn": 8}}]}', 1660606918000, 1794826836, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9306-ce202', 'stk-user9306', 'CE 202', 'doc', '{"docs": [{"id": "stk-dr-f98562", "n": "Dr. Saeid Aboud Alghamdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلام عليكم ورحمة الله وبركاته\n\nشكلي انا الوحيد من طلاب البتروليوم اللي يقيم الموضيع :sneezing_face: (انا اللي اسئل وانا اللي اجاوب بس يمكن فيه احد محتاج ما ادري لعل وعسى…)\n\nالمادة :-ce-202\nالشرح :-عادي وبعض الاحيان ماينفهم, مايحب احد يقاطعة لكن ماعليك منه اذا عندك سؤال او مافهمت شيئ في شرحة وقفة واسئل .مايحب اللي يجون متأخر يقعد يصرخ عليهم وهزئهم ولا يحب اللي يسولفون ولا اللي يلعبون بالجوال واذا ضحكت على احد من الطلاب راح يفشلك (نوعا ما الدكتور عصبي )\nالكويزات :- تقريبا تشبه الكويزات القديمة ومع بعض التغيير ونفس الحال مع المياجر والفاينل يعني اللي راح يحفظهم درجته مضمونه انشاء الله.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1432643-ce202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-saeid-aboud-alghamdi/98562/11", "user": "user9306", "ts": 1447064197000, "tid": 98562, "pn": 11}}]}', 1447064197000, 1794826836, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-cpc_2015-ce202', 'stk-cpc_2015', 'CE 202', 'doc', '{"docs": [{"id": "stk-dr-f98562", "n": "Dr. Saeid Aboud Alghamdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 202 - Term 162\n\nالتحضير : يحضر بداية الكلاس ينادي على الأسماء ، و اللي يجي متأخر يخليه يمسح السبورة ثم يحضره ! ، في أيام ينسى يحضر فيها\n\nطريقة الشرح : سيء جدا جدا جدا ، ما ينفهم منه شيء ، إضافة على ذلك الرجل فوضوي بشكل غير إعتيادي ، أفكاره غير مرتبة في الشرح ، وحتى كتابته فوضوية ، تحصله يكتب بمكان من ثم ينقز على مكان ثاني ، زيارة واحدة لموقعه في الجامعة تعطيك تصور كافي على مدى فوضويته The_Main_Page\n\nالكويزات : كان مخليها كلها تيك هوم كويز ، ونفس الكوزات القديمة ، على أننا كنا نحلها نفس الكي سولوشن للأولد كوز كنا ناخذ 80 من 100 بقدرة قادر !\n\nالمياجر: ما أقدر أقيم صعوبتها و سهولتها ، لأننا محنا بفاهمين الماتيريال ، وكنا حقيقة نحفظ المياجر القديمة و ندعو أن تجي نفسها ، الميجر الأول غيّر عن المياجر القديمة بشكل كامل فجبنا العيد ، و الميجر الثاني و الفاينل جا نفس الاولد اقزامز مع تعديلات في بعض الأفكار و إضافة لبعض التركات ، أفرج الميجر الأول كان 50 و الثاني 70\n\nالفاينلات : على ماتيريال ما بعد الميجر الثاني و جا مثل الأولد إقزامز\n\nالقريد النهائي: F و بجدارة\n\nإضافات : المادة بتتعبك من ناحية الواجبات ، 15 واجب كل اسبوع في تسليم واجب، و أسئلة كل واجب طويلة وغثيثة ، وغالبا راح يتأخر الدكتور قس المنهج آخر الأسابيع فبيضغطكم في الواجبات على أخر أسبوع ، وبعد كالهضغط الواجبات عليها 5 % من الكورس فقط. و فوق كذا من الممكن أنك تدرس المادة وتطلع فيها بقريد و أنت منت بفاهم شي !", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1473861-ce202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-saeid-aboud-alghamdi/98562/12", "user": "CPC_2015", "ts": 1495797916000, "tid": 98562, "pn": 12}}]}', 1495797916000, 1794826836, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12081-ce202', 'stk-user12081', 'CE 202', 'doc', '{"docs": [{"id": "stk-dr-f98583", "n": "Dr. A. Al-Gadhib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE202 - 202\n\nالتحضير:\nما يحرص على التحضير كثير , كان يقول انه يحمل التحضير من البلاكبورد لكن الظاهر انه ما كان يحمله.\nالشرح:\nالدكتور شرحه وافي , وهو أفضل الدكاترة اللي يشرحون هالمادة (طبعا ما فيه غنى عن جيف هانسون الله يسعده ويشرح صدره للاسلام لانه رجل مثله ما يستاهل يدخل النار :no_entry_sign:)\nالكويزات:\nبداية الترم كان يعطي كل أسبوع كويز , لكن بعد ما انضغطت الامور صار يخفف علينا أو يخليه take home quiz. لكن عالعموم كثرة كويزاته كانت شيء ايجابي , لانه الفاينل والميد افكارها من الهووموركات + الكويزات.\nالميد:\nكومون.\nالفاينل:\nكومون.\nالقريد النهائي:\nA++++++++++++\nاذا جاتك فرصة تنزل عنده لا تضيعها , الدكتور عسل وخلوق. بيعطيك نصايح في الحياة وبيعطيك نصايح في البناء والكونكريت وكلها امور خارجه عن المنهج لكن رجل بمثل هذي الخبرة احرص على كل ما يقول.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530037-ce202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-a-al-gadhib/98583/21", "user": "user12081", "ts": 1621639156000, "tid": 98583, "pn": 21}}]}', 1621639156000, 1794826836, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.x99-ce202', 'stk-mr.x99', 'CE 202', 'doc', '{"docs": [{"id": "stk-dr-f98591", "n": "Dr. Khalaf A. Al-Ofi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 202 - 211\n( الكورس جديد بالنسبة للميكانيكل )\n\nالتحضير : يسمح لك تدخل متأخر و التحضير عن طريق رقمك بالكشف ويكون نهاية الكلاس ، ما في غيابات مجانية\n\nطريقة الشرح : يشرح عن طريق سلايدات وقليل ما يستخدم السبورة ، الصراحة ان شرح الدكتور تعبان و يجيب النوووم ، شرحه عبارة عن قراءة للسلايدات فقط حتى المسائل يقرأها مع حلها بدون ما يستخدم السبورة\n\nالكويزات : سهلة الى متوسطة الا كويز واحد كان صعب و حذفه الدكتور بالنهاية ، تصحيح الدكتور لا بأس\n\nالميد : كومن ، وطريقته كل دكتور يحط سؤال و يصححه ، يعني ورقتك تمر على جميع الدكاترة\n\nالفاينلات : كومن ، نفس طريقة الميد\n\nالقريد النهائي: C+\n\nالصوت: ضعيف ويجيب النوم ، الدكتور عنده مشكلة في السمع ويستخدم سماعات لتقوية السمع ومع ذلك تحتاج تحتاج تعيد سؤالك مرة او مرتين حتى يسمعك الدكتور\n\nإضافات\n- الدكتور حبيب ومتعاون من ناحية اسئلة الطلاب ، ايضا اكثر من مرة يأجل تسليم الواجب او الكويز لما نكلمه\n- الدكتور اعطانا رقمه عشان نتواصل معه واتس و الصراحة كان يرد بسرعة\n- واجبات الدكتور كثيرة مقارنة بغيره من الدكاترة ، اعطانا 9 واجبات و بعض السكاشن الثانية اخذوا 6 ، ايضا الواجبات شبه اسبوعية وتجيك وقت المياجر و الضغط ، لدرجة مرة نزل واجبين مع بعض وتسليمهم بينه يوم مدري يومين\n\nبشكل عام ما انصح بالدكتور كخيار اول لانك بتأخذ المادة سلف ستدي 100% ، مع ذلك يمديك تطلع بقريد (هذا اللي سويته وطلعت ب A)\n( انصح بمقاطع الاسطا او ابراهيم عكه او جيف هانسون )", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533468-ce202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-khalaf-a-al-ofi/98591/4", "user": "Mr.X99", "ts": 1642194513000, "tid": 98591, "pn": 4}}]}', 1642194513000, 1794826836, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-anon63725347-ce202', 'stk-anon63725347', 'CE 202', 'doc', '{"docs": [{"id": "stk-dr-f118685", "n": "Dr. Muhammad S. Vohra", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 202\nTERM 223\n\nالتحضير :\n\nالدكتور ما يحب التأخير ، لكنه متعاون ويمشي ، ولا يخصم على الغياب\n\nالكويزات والواجبات:\n\nكانت سهللة جدا وياخذها جاهزة من كويزات و واجبات الاسطا\n\nالشرح :\n\nشرح عادي جدا احيانا تفهم وأحيانا لا ، ما يفصل بالمسائل يشرحها غالبا بشكل عام . ولكن إذا جيته في الاوفيس اور وسألته رح يحاول يفهمك بالي يقدر\n\nالاختبارات والتصحيح:\n\nالميد كان مررره سهل لدرجة ان الافرج كان 88 والفاينل خلاه صعب عشان يضبط الافرج .\n\nيده خفيفه في التصحيح ويحاول يعطيك قد ما يقدر من الدرجات لكن إذا طريقته وبدايتك غلط غالبا ما رح يعطيك .\n\nالقريدات:\n\nالدكتور كان كريييم جدا في القريدات ودف كل واحد من الطلاب قريد على القريد الي يستحقه.\n\nطبعا في ذاك الترم كان هو الي يدرس المادة والكوردنيتر فحرفيا كان كل شيء في يده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536868-ce202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhammad-s-vohra/118685/12", "user": "anon63725347", "ts": 1692751904000, "tid": 118685, "pn": 12}}]}', 1692751904000, 1794826836, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulalmazni-ce202', 'stk-abdulalmazni', 'CE 202', 'doc', '{"docs": [{"id": "stk-dr-f152669", "n": "Dr. Mohammed Al-Osta", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce202 - 202\nالتحضير : مرن جدا وما يدقق على تأخير, وبنهاية الترم اعطى الكل فل بالتحضير\nطريقة الشرح : شرح واضح وكافي ووافي ما يقصر معاك وماعنده مشكله يعيد لين تفهم\nالكويزات : وسط البداية كانت سهلات بحكم المنهج.\nالمياجر:\ncommon\nالفاينلات :\ncommon\nالقريد النهائي:\nA++++\nالصوت:\nواضح جدا و بتكلم العربية غالبا\nإضافات : أفضل دكتور مر علي بالجامعة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531511-ce202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-mohammed-al-osta/152669/16", "user": "AbdulAlmazni", "ts": 1630019351000, "tid": 152669, "pn": 16}}]}', 1630019351000, 1794826836, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sovereignsm-ce202', 'stk-sovereignsm', 'CE 202', 'doc', '{"docs": [{"id": "stk-dr-f176818", "n": "Dr. Faisal Mukhtar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 202 - 202\nالتحضير :\nبداية السمستر كان يسأل واللي ما يرد حتى ولو ب I don’t know يغيبه بعدين صار يركز على عدد من الطلاب و هو يسأل ( الدوافير) واذا ما كانوا متفاعلين يجحفل السكشن ويحضر في نص المحاضرة. ومهما يكون وسواء سأل او ما سأل حضر في بداية/ نص المحاضرة او لا لازم يرجع يحضر نهايتها ويوميا. يعني طبيعي انه يحضر اكثر من مره في المحاضرة الوحدة.\n\nطريقة الشرح :\nيشرح من سلايدات لCE201 و CE203 لان منهج CE 202 عبارة عن منهج المادتين في واحد. شرحه سيء جدا وعبارة عن قراءة فقط واذا وصل للمسائل يا يقراها ويرسم نفس الرسمه قدامك ويشخمط يمين ويسار ويضيعك او يقولك سهله جدا ما يحتاج اشرحها. وكثير يغلط في شرحه ويسأل اسئله ركيكة وما تساعد الطالب على استيعاب الكونسبت.\n\nالهورموركات: من الكوردنيتور تقريبا اغلبها نسخ لصق من ترم ٢٠١ مع تغيير ارقام لكن بينما الكوردنيتور والدكتور العوفي يأجلون للطلاب الديدلاين, الدكتور فيصل كان دائما يرفض يأجل وكان ينزل الهوموركات يومين ثلاثه متاخر عن الكوردنيتور فبالتالي سكاشنه يكون عندها اقل من اسبوع على نهاية التسليم. ويحب يحط التسليم ١٢ الظهر عشان يحشر المتاخرين ولكن مره واحدة تاجل واجب وقعد يتمنن علينا به واكتشفنا بعدها انه من الكوردنيتور وليس منه. طبعا المادة كوردنيتد ولكن بشكل غريب ما فيه شيء موحد غير اسئلة الفاينل.\n\nالكويزات : متوسطة الصعوبة ودائما يكون فيها اخطاء و مشاكل وهو الوحيد هذا الترم اللي كويزاته MCQ مع ان المادة ما تنفع لهذا النظام ويحب يحط خيار none of the answers عشان تكون مخرج له لو طلع في السؤال غلط وعشان يوقع اكبر عدد من الطلاب فيها اذا ما طلعوا الحل الصحيح من البداية. كما ان الخيارات تكون متقاربه جدا يعني بتلقى ثلاثه اجوبه من بين خمس- ثمانيه خيارات فيها نفس الارقام بس الفرق في الاتجاه. ومن ناحية تنظيمه للكويزات سيء جدا. اول كويز كان بدون باك تراكنق و ٥ اسئلة في ١٥ دقيقة ما توصل السؤال الاخير الا الوقت انتهى. الكويزات اللي بعدها زود ٥ دقايق وصار فيه باك تراكنق لكن زادت صعوبتها وفيه كويز طلب لوكداون واخر دقيقة غير رايه. مستحيل يبدا الكويز في الوقت اللي يقوله لك لازم يتاخر ٥-١٠ دقايق وياخذها من وقت البريك اللي بين الكلاسات. ويشغلك طول الكويز يقعد يعلق على صور عرض الشباب ولا كاميراتهم والخ.\n\nالميد: كومن من كتابة الكوردنيتور علي القضيب انصح بحضور المحاضرات معاه والهلب سشنز اللي يعطيها لطلابه لانه يلمح للاسئلة وافهم يا فهيم. ولكن د. فيصل غير كم رقم وكم شيء في الاسئلة وضيع علينا اكثر من ساعه وهو يحاول يعدلها بشكل مستفز. يسوي شير سكرين ويورينا السؤال الصحيح لمدة دقيقتين ويقفل ونقعد نطلبه يفتح من جديد عشان نشوف وين الاختلاف. للاسف ما عرف يتعامل مع اخطاءه نهائيا وترك الاجوبة المبرمجة على نفس حقت القضيب رغم الاختلافات الى ان تواصلنا مع الشيرمان.\n\nالفاينلات : كومن , نفس كلامي عن الميد بس الفرق كانت موحدة في صفحة واحدة لكل الطلاب عكس الميد.\nالقريد النهائي: F\nالصوت: واضح\nإضافات :\nالدكتور فيصل أول مرة يدرس CE 202 هذا الترم , لكن الوضع كان سيء جدا ما يعرف يعطيك معلومة مفيدة عن وضعك انت او الكورس بشكل عام كل شيء يقول انتظر الكوردنيتور يعلمني. ايضا اخلاق الدكتور لك عليها وتعامله في بعض المواقف مع الطلاب فيه عدم ثقة وتقدير للطالب بشكل واضح. في فترة التقييم راح تسمع منه وعود واشياء تبسطك لكن ما راح يطبقها وخذها من مجرب. هو فعلا كان اسوء دكتور في المادة هذا السمستر ولكن لما تناقشت معاه في الاوفس اور عن موضوع مهم في الدرجات اكتشفت ان الادمي مصدق انه افضل دكتور في المادة. لا تنزل معاه ابدا واهرب منه. من الاخر نزل مع اي دكتور ثاني.\n\nاذا انجبرت عليه بتحتاج تكون معطي المادة فوق ١٠٠٪؜ عشان تجيب قريد كويس وتعود انك تراجع درجاتك واجوبتك وتسجلها دائما لان هو والقريدر يخطون كثير في التصحيح او وضع الاجوبة للكويز او غيره وما يدري الا بعد ما ترسله ٣ ايميل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529998-ce202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-mukhtar/176818/6", "user": "sovereignsM", "ts": 1621467458000, "tid": 176818, "pn": 6}}]}', 1621467458000, 1794826836, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12192-ce202', 'stk-user12192', 'CE 202', 'doc', '{"docs": [{"id": "stk-dr-f176818", "n": "Dr. Faisal Mukhtar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 202 - 211\n\nالتحضير : نهاية الكلاس\nطريقة الشرح : يشرح من السلايدات ثم يحل الأسئلة، أشوف شرحه كان جيد إلى ممتاز قبل الميد، وبعد الميد ما صرت اركز في الكلاس.\nالكويزات : 6 كويزات (سؤال من الواجب) وأخذ أفضل 5، كان يأجل إذا وافق أغلب الطلاب في الغالب (إذا كان مناسب) ، الكويز آخر الكلاس لمدة 10-15 دقيقة\nالواجبات: 9 وكان يأجل إذا انطلب في الغالب (إذا كان مناسب) والتسليم في الكلاس، كم مرة سلم طالب الواجب الكلاس اللي بعده وكان ياخذه (بس ما ادري هل يخصم او لا)\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: واضح، اللغة ممتازة ولهجته مؤثرة بشكل خفيييف.\nإضافات : انصح به، الطلاب اللي درسوا عنده اونلاين اشتكوا منه وتشوفون التعليقات فوق، لكن يبدو الدكتور اثر عليه الاونلاين و تعامل القسم مع الوضع في الاونلاين ما كان جيد فاثر على تجربة الشباب، لكن الدكتور تغير 180 درجة. كان بيسوي بروجت بونص عبارة عن برزنتايشن عن امثلة من واقع الحياة من مواضيع المادة لكن كنسله وحط واجب بونص (5 أسئلة).", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533299-ce202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-mukhtar/176818/7", "user": "user12192", "ts": 1641322088000, "tid": 176818, "pn": 7}}]}', 1641322088000, 1794826836, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
